/// <summary>
/// MPJ_24248 Pricing Data Extract DCP 28/07/2022
/// </summary>
[ExtensionOf(ClassStr(GUPNumberSeqModule))]
final class METGUPNumberSeqModule_Extension
{
}

Method.Source:
    /// <summary>
    /// Load Enty number
    /// </summary>
    protected void loadModule()
    {
        NumberSeqDatatype datatype = NumberSeqDatatype::construct();

        next loadModule();

        /* Setup Entry number */

        datatype.parmDatatypeId(extendedTypeNum(METEntryId));
        datatype.parmReferenceLabel(literalStr("@MET:EntryNumber"));
        datatype.parmReferenceHelp(literalStr("@MET:EntryNumber_NumberSeqHelp"));
        datatype.parmWizardIsContinuous(false);
        datatype.parmWizardIsManual(NoYes::No);
        datatype.parmWizardIsChangeDownAllowed(NoYes::No);
        datatype.parmWizardIsChangeUpAllowed(NoYes::No);
        datatype.parmIsGroupEnabled(NoYes::Yes);
        datatype.parmWizardHighest(2147483647);
        datatype.parmSortField(100);

        datatype.addParameterType(NumberSeqParameterType::DataArea, true, false);
        this.create(datatype);
    }
